CodeCell.Script:
Console.WriteLine("Hello from .NET running in your browser.");
Console.WriteLine($"The World contains {world.Count} entities.");

world.Create(HList.From(
    new Message("Stored in the shared World.")));

Notebook.Render("Entity created.");

public readonly record struct Message(string Text);

Console.WriteLine($"The shared scope contains {world.Count} entity.");
foreach (var entity in world.Query(Matchers.Of<Message>())) {
    Console.WriteLine($"message: {entity.Get<Message>().Text}");
}

var found = world.Query(Matchers.Of<Message>()).Count;
Console.WriteLine($"Messages in the isolated World: {found}");
Notebook.Render(found == 0 ? "No shared messages." : "Message found.");

public readonly record struct Message(string Text);

var roster = new[] {
    world.Create(HList.From(new Player("Aki", 12))),
    world.Create(HList.From(new Player("Ben", 27))),
    world.Create(HList.From(new Player("Cy", 9))),
};
Console.WriteLine("Created three players.");

public readonly record struct Player(string Name, int Score);

public static class Scoring
{
    public static int Total(World world)
    {
        var total = 0;
        foreach (var entity in world.Query(Matchers.Of<Player>())) {
            total += entity.Get<Player>().Score;
        }
        return total;
    }
}

foreach (var entity in world.Query(Matchers.Of<Player>())) {
    var player = entity.Get<Player>();
    Console.WriteLine($"{player.Name,-4} {player.Score,3}");
}
Notebook.Render($"{world.Count} players · {Scoring.Total(world)} points");
